WFJ.Data.add("book", {
  ["ea0a01941266a1af"] = { "そこでこの勇敢な開拓者たちは、宇宙的なWell of Eternityを発見し、それによって計り知れない力を持つ存在へと変えられた。これら冒険心あふれるトロールこそ最初のナイトエルフであったとする伝説もあるが、この説が証明されたことはない。", "." },
  ["ea2630357f94edfd"] = { "Hand of Dagun\n\n古い文献によれば、Dagunの鉤爪は獲物を殺さない毒を分泌し、その代わりに獲物を別のもの――古き種族の一員――へと変異させるという。それが我々にとって価値あるものであることは疑いない。\n\nDagunは深海に棲むが、Dustwallow MarshのMirefin Murlocの部族によって、たびたび海面へおびき出されている。その部族のオラクルたちが、魔法をかけた海藻で奴を呼び出すのだ。オラクルを十分に倒せば、その海藻が見つかるだろう。それをMurlocの祭壇に置けば、Dagunが現れる。", "." },
  ["ea4dbe72b19e08fa"] = { "Morgan Ladimoreは、罪なき者、貧しき者、苦しむ者を守るために戦った、偉大で高潔な騎士であった。長年にわたり、彼はAzerothの辺境の地を熱心に巡り、苦しむ者に救いを、悪をなす者に迅速な裁きをもたらした。\n\n彼は十八の年の夏、Lysという名の若い娘と結婚した。二人は深く愛し合い、やがて3人の子供、息子一人と2人の娘をもうけた。\n\nMorganが32歳のとき、戦争が勃発した。場所は", "." },
  ["ea96ef50e8e42705"] = { "LORD VALTHALAK(続き)……\n\nアミュレットをいくつかの欠片に分け、我々は新たに蘇ったValthalakの亡霊と、その亡霊の暗殺者の軍勢から逃げ出した。しかも、アミュレットをめぐって争った騒ぎのせいで、Spireに残っていた守備兵の多くが目を覚ましていたのだ！\n\n我々のほぼ全員がBlackrockを抜け出し、もう安全だと思った。だがValthalakは、あの世からでさえ、我々がどこに隠れようとも手下を差し向けてきた。その任務の後ほどなくしてThe Veiled Bladeは崩壊し、そうなると我々は本当にたやすい獲物だった。\n\n知っての通り、これによりLord Valthalakの住処、すなわち現在Blackrock SpireでThe Beastの部屋となっている場所が、最後の呪われた場所となる。", "." },
  ["eaa7c08990effa2e"] = { "ArthasとそのScourgeはQuel'Thalasに侵攻し、崩れかけたエルフの防衛線を包囲した。Silvermoonのレンジャー将軍Sylvanas Windrunnerは勇敢に戦ったが、Arthasはついにhigh elfの軍を根絶やしにし、Sunwellまで戦い抜いた。自らの支配を誇示する残酷な仕打ちとして、彼は敗れたSylvanasの亡骸をbansheeとしてよみがえらせさえした。彼女はQuel'Thalasの征服者に仕え、終わりなき不死の身に呪われたのである。", "." },
  ["eaaa9493620afaf5"] = { "彼らは永遠の命を得て、来たるべきSunderingを何ら恐れることはない、と……", "." },
  ["eaf2026693a6e7d1"] = { "この混乱のさなか、ひとりの謎めいた預言者が現れ、定命の種族を導いた。この預言者こそ、最後の守護者Medivhにほかならなかった。彼は過去の罪を償うため、Beyondから奇跡的に戻ってきたのである。MedivhはHordeとAllianceに、彼らが直面する危険を告げ、手を結ぶよう促した。", "." },
  ["eaf6410a59d6f845"] = { "トロールの伝説によれば、Stone of the Tidesが初めてGurubashi Empireにもたらされたとき、それを見つけたのはStranglethornの海岸をさまよっていた一人のトロールのウォリアーであった。彼は、乳白色の筋が中で漂い流れる、不思議な青い石に出くわした。その石に興味を引かれたウォリアーは、それを携えて旅を続けた。\n\n数週間、数か月が過ぎるうちに、ウォリアーはその石が自分に水を操る力を与えたことに気づいた。彼は呼び出すことができた。", "." },
})
